import{_ as t,o as r,c as o,a3 as i}from"./chunks/framework.DBpCFmh2.js";const d=JSON.parse('{"title":"MCP 协议规范","description":"本规范面向 AI Helper Agent 的 MCP（Model Context Protocol）扩展能力，说明当前实现如何发现、连接、调用第三方 MCP Server，并把其工具注入到统一工具列表中。","frontmatter":{"title":"MCP 协议规范","description":"本规范面向 AI Helper Agent 的 MCP（Model Context Protocol）扩展能力，说明当前实现如何发现、连接、调用第三方 MCP Server，并把其工具注入到统一工具列表中。"},"headers":[],"relativePath":"API-参考文档/MCP-协议规范/index.md","filePath":"API-参考文档/MCP-协议规范/index.md","lastUpdated":null}'),l={name:"API-参考文档/MCP-协议规范/index.md"};function a(c,e,n,s,g,h){return r(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="mcp-协议规范" tabindex="-1">MCP 协议规范 <a class="header-anchor" href="#mcp-协议规范" aria-label="Permalink to &quot;MCP 协议规范&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js" target="_blank" rel="noreferrer">agent/src/mcp/client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js" target="_blank" rel="noreferrer">agent/src/mcp/registry.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/docs/MCP-UPGRADE-ANALYSIS.md" target="_blank" rel="noreferrer">agent/docs/MCP-UPGRADE-ANALYSIS.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-test-server.cjs" target="_blank" rel="noreferrer">agent/test/mcp-test-server.cjs</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-client-test.js" target="_blank" rel="noreferrer">agent/test/mcp-client-test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md" target="_blank" rel="noreferrer">agent/README.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/en.js" target="_blank" rel="noreferrer">src/shared/locales/en.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/zh.js" target="_blank" rel="noreferrer">src/shared/locales/zh.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与可靠性">性能与可靠性</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录协议版本工具定义与集成示例">附录：协议版本、工具定义与集成示例</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本规范面向 AI Helper Agent 的 MCP（Model Context Protocol）扩展能力，说明当前实现如何发现、连接、调用第三方 MCP Server，并把其工具注入到统一工具列表中。文档同时给出协议版本兼容性策略、工具定义格式、消息与错误处理约定、工具注册机制、以及 Python/Node.js 客户端集成参考路径。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>Agent 端的 MCP 功能集中在 <code>agent/src/mcp</code> 三个模块中：</p><ul><li><code>client.js</code>：封装单个 MCP Server 的连接、传输层选择、工具列表获取与工具调用。</li><li><code>registry.js</code>：维护多个 MCP Client 实例，提供启动时自动连接、状态查询、扁平化工具列表和工具调用路由。</li><li><code>mcp-config.js</code>：持久化 MCP Server 配置（<code>~/.ai-helper-agent/mcp_servers.json</code>），提供增删改查与写锁保护。</li></ul><pre class="mermaid">graph TB
subgraph &quot;Agent 进程&quot;
REG[&quot;registry.js&lt;br/&gt;多 Server 注册表&quot;]
CFG[&quot;mcp-config.js&lt;br/&gt;配置管理&quot;]
CLI[&quot;client.js&lt;br/&gt;单 Server 客户端&quot;]
end
EXT[&quot;Chrome 扩展&lt;br/&gt;选项页 / 侧边栏&quot;]
API[&quot;Agent HTTP API&lt;br/&gt;/api/mcp/*&quot;]
S1[&quot;MCP Server A&lt;br/&gt;stdio/SSE/HTTP/WebSocket&quot;]
S2[&quot;MCP Server B&lt;br/&gt;stdio/SSE/HTTP/WebSocket&quot;]
EXT --&gt; API
API --&gt; REG
REG --&gt; CFG
REG --&gt; CLI
CLI --&gt; S1
CLI --&gt; S2
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li><strong>McpClient</strong>：负责单一 MCP Server 的生命周期，包括传输层创建、连接、工具发现、工具调用与断开。</li><li><strong>Registry</strong>：集中管理所有已连接的 McpClient，暴露初始化、状态查询、工具列表聚合、工具调用入口。</li><li><strong>Config</strong>：负责 MCP Server 配置的加载、保存、添加、删除、启用/禁用，并提供内存缓存与写入互斥锁。</li></ul><p>关键职责边界：</p><ul><li>协议细节由 SDK 与 <code>client.js</code> 承担；</li><li>多 Server 并发与工具聚合由 <code>registry.js</code> 承担；</li><li>配置持久化与权限校验由 <code>mcp-config.js</code> 与上层 server 路由承担。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L19-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L19-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L11-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L11-L129</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>Agent 作为 MCP 客户端，通过 JSON-RPC 2.0 与外部 MCP Server 通信。Agent 启动时自动连接所有启用的 MCP Server，拉取工具列表并合并为全局工具集；当扩展端需要执行某个 MCP 工具时，Agent 将请求转发给对应 Server，再把结果返回给扩展端。</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展端&quot;
participant Api as &quot;Agent HTTP API&quot;
participant Reg as &quot;MCP 注册表&quot;
participant Cli as &quot;MCP 客户端&quot;
participant Srv as &quot;MCP Server&quot;
Ext-&gt;&gt;Api : &quot;GET /api/mcp/tools&quot;
Api-&gt;&gt;Reg : &quot;getMcpTools()&quot;
Reg-&gt;&gt;Cli : &quot;读取已连接 Server 的工具列表&quot;
Cli--&gt;&gt;Reg : &quot;tools[]&quot;
Reg--&gt;&gt;Api : &quot;{success, tools}&quot;
Api--&gt;&gt;Ext : &quot;工具清单&quot;
Ext-&gt;&gt;Api : &quot;POST /api/mcp/ : serverId/connect&quot;
Api-&gt;&gt;Reg : &quot;connectMcpServer(serverId)&quot;
Reg-&gt;&gt;Cli : &quot;connect()&quot;
Cli-&gt;&gt;Srv : &quot;建立连接 + listTools&quot;
Srv--&gt;&gt;Cli : &quot;工具列表&quot;
Cli--&gt;&gt;Reg : &quot;连接成功&quot;
Reg--&gt;&gt;Api : &quot;连接结果&quot;
Api--&gt;&gt;Ext : &quot;连接状态&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L154" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L154</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L127</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="组件一-mcpclient" tabindex="-1">组件一：McpClient <a class="header-anchor" href="#组件一-mcpclient" aria-label="Permalink to &quot;组件一：McpClient&quot;">​</a></h3><p>McpClient 是单个 MCP Server 的抽象，封装了以下能力：</p><ul><li>根据配置选择传输层：stdio、SSE、Streamable HTTP、WebSocket。</li><li>使用 SDK 的 <code>Client</code> 进行连接，获取服务端版本、能力与工具列表。</li><li>调用工具时把 SDK 返回的结构转换为统一的 <code>{success, content, raw}</code> 或失败对象。</li><li>提供 <code>getStatus()</code> 用于对外展示连接状态、工具数量与服务端信息。</li></ul><pre class="mermaid">classDiagram
class McpClient {
+string serverId
+string serverName
+object serverConfig
+object client
+object transport
+boolean connected
+array tools
+object serverInfo
+connect() Promise~object~
+callTool(toolName, args) Promise~object~
+disconnect() Promise~void~
+getStatus() object
-_createTransport() object
}
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li></ul><p>关键行为说明：</p><ul><li>连接成功后会调用 <code>listTools({})</code> 获取工具列表，并缓存到 <code>this.tools</code>。</li><li>工具调用失败时，优先使用 SDK 返回的 <code>error.message</code>，否则回退到本地翻译的错误提示。</li><li>工具返回内容按 <code>type === &#39;text&#39;</code> 过滤后拼接成文本字符串，便于模型消费。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L47-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L47-L184</a></li></ul><h3 id="组件二-mcp-工具注册表-registry" tabindex="-1">组件二：MCP 工具注册表 Registry <a class="header-anchor" href="#组件二-mcp-工具注册表-registry" aria-label="Permalink to &quot;组件二：MCP 工具注册表 Registry&quot;">​</a></h3><p>Registry 维护一个 <code>Map&lt;serverId, McpClient&gt;</code>，提供：</p><ul><li>启动时自动连接所有 <code>enabled: true</code> 的 MCP Server。</li><li>查询所有已连接 Server 的状态与工具。</li><li>扁平化输出工具列表，包含 <code>serverId</code>、<code>serverName</code>、<code>name</code>、<code>description</code>、<code>inputSchema</code>。</li><li>路由工具调用到具体 Server。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;初始化&quot;]) --&gt; LoadCfg[&quot;加载 mcp_servers.json&quot;]
LoadCfg --&gt; ForEach[&quot;遍历 servers&quot;]
ForEach --&gt; Enabled{&quot;是否启用?&quot;}
Enabled --&gt; |否| Next[&quot;下一个 Server&quot;]
Enabled --&gt; |是| Connect[&quot;创建 McpClient 并 connect&quot;]
Connect --&gt; Connected{&quot;连接成功?&quot;}
Connected --&gt; |是| Register[&quot;注册到 clients Map&quot;]
Connected --&gt; |否| RecordFail[&quot;记录失败 Server&quot;]
Register --&gt; Next
RecordFail --&gt; Next
Next --&gt; Done([&quot;完成&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L55</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L19-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L19-L181</a></li></ul><h3 id="组件三-mcp-配置管理" tabindex="-1">组件三：MCP 配置管理 <a class="header-anchor" href="#组件三-mcp-配置管理" aria-label="Permalink to &quot;组件三：MCP 配置管理&quot;">​</a></h3><p>配置存储在 <code>~/.ai-helper-agent/mcp_servers.json</code>，默认结构为 <code>{ servers: [] }</code>。模块提供：</p><ul><li>带 mtime 缓存的 <code>loadMcpConfig()</code>。</li><li>带 Promise 写锁的 <code>saveMcpConfig()</code>。</li><li><code>addMcpServer()</code>、<code>removeMcpServer()</code>、<code>toggleMcpServer()</code>。</li></ul><pre class="mermaid">flowchart TD
Read[&quot;读取 mcp_servers.json&quot;] --&gt; CacheCheck{&quot;mtime 未变化?&quot;}
CacheCheck --&gt; |是| ReturnCache[&quot;返回内存缓存&quot;]
CacheCheck --&gt; |否| Parse[&quot;解析 JSON&quot;]
Parse --&gt; Valid{&quot;servers 字段存在?&quot;}
Valid --&gt; |否| InitDefault[&quot;初始化 servers=[]&quot;]
Valid --&gt; |是| UpdateCache[&quot;更新缓存与 mtime&quot;]
InitDefault --&gt; UpdateCache
UpdateCache --&gt; Return[&quot;返回配置&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L28-L64" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L28-L64</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li><code>registry.js</code> 依赖 <code>client.js</code> 与 <code>mcp-config.js</code>。</li><li><code>client.js</code> 依赖官方 SDK：<code>@modelcontextprotocol/sdk</code> 及其传输层模块。</li><li>扩展端通过 Agent HTTP API 访问 MCP 能力，UI 在选项页中管理 Server 配置。</li></ul><pre class="mermaid">graph LR
REG[&quot;registry.js&quot;] --&gt; CLI[&quot;client.js&quot;]
REG --&gt; CFG[&quot;mcp-config.js&quot;]
CLI --&gt; SDK[&quot;@modelcontextprotocol/sdk&quot;]
EXT[&quot;options/toolbox-mcp.js&quot;] --&gt; API[&quot;Agent HTTP API&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L5" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L5</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L6" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L1-L24" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L1-L24</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/toolbox-mcp.js#L1-L43" target="_blank" rel="noreferrer">src/options/toolbox-mcp.js#L1-L43</a></li></ul><h2 id="性能与可靠性" tabindex="-1">性能与可靠性 <a class="header-anchor" href="#性能与可靠性" aria-label="Permalink to &quot;性能与可靠性&quot;">​</a></h2><ul><li>配置读写采用内存缓存与文件 mtime 判断，避免频繁磁盘 I/O。</li><li>配置写入使用 Promise 链式写锁，防止并发写导致数据损坏。</li><li>每个 HTTP 请求处理器有异常捕获，避免单个错误拖垮服务。</li><li>MCP 子进程与命令执行共享 Agent 的安全分级与审计日志体系。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L18-L26" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L18-L26</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L279-L289" target="_blank" rel="noreferrer">agent/README.md#L279-L289</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><p>常见现象与定位建议：</p><ul><li>新增 MCP Server 后无法连接： <ul><li>检查 <code>mcp_servers.json</code> 中 <code>id</code>、<code>command</code> 或 <code>url</code> 是否填写正确。</li><li>stdio 模式需确保命令可执行；HTTP 模式需确保 URL 可达。</li><li>查看 Agent 控制台日志中的 <code>[MCP]</code> 前缀信息。</li></ul></li><li>工具列表为空： <ul><li>确认 Server 已成功连接；<code>getMcpServersStatus()</code> 会返回 <code>connected</code> 与 <code>toolCount</code>。</li><li>检查 MCP Server 是否正确实现 <code>tools/list</code>。</li></ul></li><li>工具调用失败： <ul><li>查看 <code>callTool</code> 返回的 <code>error</code> 字段；SDK 层错误会被透传。</li><li>若 MCP Server 返回结构化错误，优先使用其 <code>message</code>。</li></ul></li><li>配置修改不生效： <ul><li>确认文件已保存且 mtime 发生变化；必要时重启 Agent 以重新加载配置。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L157</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L60-L108" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L60-L108</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L37-L79" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L37-L79</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>当前 Agent 对 MCP 的实现以 SDK 为核心，围绕 <code>client.js</code>、<code>registry.js</code>、<code>mcp-config.js</code> 形成“单 Server 客户端 + 多 Server 注册表 + 配置持久化”的稳定结构。它支持多种传输方式，具备自动发现工具、统一工具聚合、安全校验与 i18n 能力，适合扩展第三方工具生态。未来升级方向聚焦于协议 Modern 模式的 Dual-era 兼容与无状态化迁移。</p><h2 id="附录-协议版本、工具定义与集成示例" tabindex="-1">附录：协议版本、工具定义与集成示例 <a class="header-anchor" href="#附录-协议版本、工具定义与集成示例" aria-label="Permalink to &quot;附录：协议版本、工具定义与集成示例&quot;">​</a></h2><h3 id="协议版本兼容性" tabindex="-1">协议版本兼容性 <a class="header-anchor" href="#协议版本兼容性" aria-label="Permalink to &quot;协议版本兼容性&quot;">​</a></h3><ul><li>当前 SDK 版本为 <code>@modelcontextprotocol/sdk@^1.29.0</code>，运行在 Legacy 模式。</li><li>协议演进时间线包括 2024-11-05、2025-03-26、2025-06-18、2025-11-25，以及 2026-07-28 的无状态化版本。</li><li>当前实现通过 SDK 内部协商完成版本选择；尚未实现显式的 Dual-era 探测逻辑。</li><li>官方建议在未来引入 <code>server/discover</code> 与 <code>_meta</code> 无状态请求，并对弃用特性保留 12 个月窗口。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/docs/MCP-UPGRADE-ANALYSIS.md#L1-L23" target="_blank" rel="noreferrer">agent/docs/MCP-UPGRADE-ANALYSIS.md#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/docs/MCP-UPGRADE-ANALYSIS.md#L26-L75" target="_blank" rel="noreferrer">agent/docs/MCP-UPGRADE-ANALYSIS.md#L26-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/docs/MCP-UPGRADE-ANALYSIS.md#L78-L109" target="_blank" rel="noreferrer">agent/docs/MCP-UPGRADE-ANALYSIS.md#L78-L109</a></li></ul><h3 id="工具定义格式" tabindex="-1">工具定义格式 <a class="header-anchor" href="#工具定义格式" aria-label="Permalink to &quot;工具定义格式&quot;">​</a></h3><p>Agent 从 MCP Server 拉取的每个工具至少包含：</p><ul><li><code>name</code>：工具名称。</li><li><code>description</code>：工具描述。</li><li><code>inputSchema</code>：参数 JSON Schema；若缺失则回退为 <code>{ type: &#39;object&#39;, properties: {} }</code>。</li></ul><p>Agent 向外暴露的工具元数据包含：</p><ul><li><code>serverId</code>：来源 Server 标识。</li><li><code>serverName</code>：显示名称。</li><li><code>name</code>、<code>description</code>、<code>inputSchema</code>：来自 MCP Server 的工具定义。</li></ul><p>返回值方面，Agent 对 MCP 工具调用的统一包装为：</p><ul><li>成功：<code>{ success: true, content: string, raw: object }</code>。</li><li>失败：<code>{ success: false, error: string }</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L89-L108" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L89-L108</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L157</a></li></ul><h3 id="消息格式与错误处理" tabindex="-1">消息格式与错误处理 <a class="header-anchor" href="#消息格式与错误处理" aria-label="Permalink to &quot;消息格式与错误处理&quot;">​</a></h3><ul><li>MCP 客户端与服务端之间使用 JSON-RPC 2.0。</li><li>连接阶段：<code>connect()</code> → <code>getServerVersion()</code> → <code>getServerCapabilities()</code> → <code>listTools({})</code>。</li><li>调用阶段：<code>callTool({ name, arguments })</code>。</li><li>错误处理： <ul><li>连接失败：返回 <code>{ success: false, error }</code>。</li><li>工具调用失败：优先使用 SDK 返回的 <code>error.message</code>，否则使用本地翻译错误。</li><li>未连接时调用工具：直接返回未连接错误。</li></ul></li></ul><pre class="mermaid">flowchart TD
Entry[&quot;调用工具入口&quot;] --&gt; CheckConn{&quot;Server 已连接?&quot;}
CheckConn --&gt; |否| ErrNotConnected[&quot;返回未连接错误&quot;]
CheckConn --&gt; |是| CallSdk[&quot;调用 SDK callTool&quot;]
CallSdk --&gt; HasError{&quot;SDK 返回 error?&quot;}
HasError --&gt; |是| ErrSdk[&quot;返回 success=false + error.message&quot;]
HasError --&gt; |否| BuildResult[&quot;提取 text 内容并构建结果&quot;]
BuildResult --&gt; Ok[&quot;返回 success=true + content&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L157</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L157</a></li></ul><h3 id="工具注册机制" tabindex="-1">工具注册机制 <a class="header-anchor" href="#工具注册机制" aria-label="Permalink to &quot;工具注册机制&quot;">​</a></h3><ul><li>动态发现：启动时自动连接所有启用的 MCP Server，并调用 <code>listTools</code> 获取工具。</li><li>自动加载：<code>initializeMcpRegistry()</code> 遍历配置，逐个连接并注册到 <code>clients</code> Map。</li><li>配置管理：<code>mcp_servers.json</code> 支持添加、删除、启用/禁用 Server；UI 通过 <code>/api/mcp/servers</code> 等接口操作。</li><li>安全校验：stdio 模式下会对 <code>command + args</code> 做命令安全分级检查，高危命令直接拒绝，灰名单命令要求确认。</li></ul><pre class="mermaid">sequenceDiagram
participant UI as &quot;选项页&quot;
participant API as &quot;Agent API&quot;
participant CFG as &quot;mcp-config.js&quot;
participant REG as &quot;registry.js&quot;
UI-&gt;&gt;API : &quot;POST /api/mcp/servers&quot;
API-&gt;&gt;CFG : &quot;addMcpServer(server)&quot;
CFG--&gt;&gt;API : &quot;保存成功&quot;
API-&gt;&gt;REG : &quot;可选：触发重连或刷新工具列表&quot;
REG--&gt;&gt;UI : &quot;操作结果&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L82-L126" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L82-L126</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L55</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L55</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L82-L126" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L82-L126</a></li></ul><h3 id="mcp-服务器集成示例" tabindex="-1">MCP 服务器集成示例 <a class="header-anchor" href="#mcp-服务器集成示例" aria-label="Permalink to &quot;MCP 服务器集成示例&quot;">​</a></h3><h4 id="node-js-测试服务器" tabindex="-1">Node.js 测试服务器 <a class="header-anchor" href="#node-js-测试服务器" aria-label="Permalink to &quot;Node.js 测试服务器&quot;">​</a></h4><p>仓库提供一个最小化的 MCP 测试服务器，用于验证协议实现：</p><ul><li>支持的 RPC：<code>initialize</code>、<code>notifications/initialized</code>、<code>tools/list</code>、<code>tools/call</code>。</li><li>提供的测试工具：<code>add</code>、<code>multiply</code>、<code>echo</code>、<code>get_time</code>、<code>random_number</code>。</li><li>可通过 <code>node agent/test/mcp-test-server.cjs</code> 启动，并在 Agent 配置中使用该脚本作为 stdio 传输的命令。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-test-server.cjs#L1-L25" target="_blank" rel="noreferrer">agent/test/mcp-test-server.cjs#L1-L25</a></li></ul><h4 id="python-客户端集成参考" tabindex="-1">Python 客户端集成参考 <a class="header-anchor" href="#python-客户端集成参考" aria-label="Permalink to &quot;Python 客户端集成参考&quot;">​</a></h4><p>虽然仓库未内置 Python MCP Server 示例，但 Agent 的 MCP 客户端支持 stdio 传输，因此可以在 Python 中实现一个遵循 MCP 协议的命令行程序，并通过 Agent 配置中的 <code>command</code> 与 <code>args</code> 启动。典型步骤：</p><ul><li>安装官方 MCP SDK。</li><li>实现 <code>initialize</code>、<code>tools/list</code>、<code>tools/call</code>。</li><li>通过标准输入输出发送 JSON-RPC 2.0 消息。</li><li>在 Agent 配置中将 <code>command</code> 设为 <code>python</code>，<code>args</code> 设为 <code>-m your_mcp_server</code>。</li></ul><p>注意：Agent 会对 stdio 命令执行安全分级检查，避免 MCP 成为命令管控后门。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1868" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1868</a></li></ul><h4 id="node-js-客户端集成参考" tabindex="-1">Node.js 客户端集成参考 <a class="header-anchor" href="#node-js-客户端集成参考" aria-label="Permalink to &quot;Node.js 客户端集成参考&quot;">​</a></h4><p>Agent 自身就是 MCP 客户端，可直接复用其 <code>McpClient</code> 类：</p><ul><li>构造 <code>serverConfig</code>，包含 <code>id</code>、<code>name</code>、<code>command</code> 或 <code>url</code>、<code>transport</code>、<code>env</code>、<code>headers</code>。</li><li>调用 <code>connect()</code> 建立连接并拉取工具列表。</li><li>调用 <code>callTool(name, args)</code> 执行工具。</li><li>调用 <code>disconnect()</code> 释放资源。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/mcp-client-test.js#L1-L52" target="_blank" rel="noreferrer">agent/test/mcp-client-test.js#L1-L52</a></li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>为每个 MCP Server 设置唯一 <code>id</code> 与可读 <code>name</code>，便于区分来源。</li><li>优先使用 stdio 传输开发调试，生产环境可使用 Streamable HTTP 或 WebSocket。</li><li>敏感 Token 通过环境变量传入，不要硬编码在配置文件中。</li><li>工具描述应清晰说明用途、触发条件与参数含义，有助于模型预筛选。</li><li>对长耗时工具，建议在 MCP Server 侧做好超时与重试控制。</li><li>定期清理不再使用的 MCP Server，减少子进程与工具上下文开销。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/en.js#L1015-L1038" target="_blank" rel="noreferrer">src/shared/locales/en.js#L1015-L1038</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/zh.js#L1015-L1038" target="_blank" rel="noreferrer">src/shared/locales/zh.js#L1015-L1038</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/README.md#L366-L402" target="_blank" rel="noreferrer">agent/README.md#L366-L402</a></li></ul>`,119)])])}const u=t(l,[["render",a]]);export{d as __pageData,u as default};
